import {chineseVoice} from '../services/audio.js';
let readingEpoch=0,readingUtterance=null,readingRecording=null;
/** A single owner for all reader playback. onend drives sequences, never guessed timings. */
export function stopReadings(){readingEpoch++;if(typeof window!=='undefined'&&window.speechSynthesis)window.speechSynthesis.cancel();readingUtterance=null;if(readingRecording){readingRecording.pause();readingRecording=null}}
export function speakReadings(texts,speed,onActive,onStatus){stopReadings();const epoch=readingEpoch,voice=chineseVoice();if(!voice){onStatus('No Mandarin voice available. Enable a Mandarin voice on this device.');return}let at=0;
 function next(){if(epoch!==readingEpoch)return;if(at>=texts.length){onStatus('Playback finished');return}if(texts[at].audio){const audio=new Audio(texts[at].audio);readingRecording=audio;audio.playbackRate=speed;audio.onended=()=>{if(epoch===readingEpoch){at++;next()}};audio.onerror=()=>{if(epoch===readingEpoch)onStatus('Recorded audio failed. Try device voice or check the resource.')};onActive(texts[at].id);audio.play().catch(()=>onStatus('Audio blocked. Press Replay.'));return}const u=new SpeechSynthesisUtterance(texts[at].text);readingUtterance=u;u.voice=voice;u.lang=voice.lang;u.rate=speed;u.onstart=()=>{if(epoch===readingEpoch){onActive(texts[at].id);onStatus('Playing')}};u.onend=()=>{if(epoch===readingEpoch){at++;next()}};u.onerror=e=>{if(epoch===readingEpoch&&!['canceled','interrupted'].includes(e.error)){onStatus('Audio failed. Try Replay or a different device voice.');stopReadings()}};window.speechSynthesis.speak(u)}next();}
export function pauseReading(){if(readingUtterance&&window.speechSynthesis?.pause)window.speechSynthesis.pause()}
export function resumeReading(){if(readingUtterance&&window.speechSynthesis?.resume)window.speechSynthesis.resume()}
